// Catalog data — generated by tools/gen-catalog.mjs into artifacts.json.
// Do not hand-edit artifacts.json; re-run the generator instead.

import raw from "./artifacts.json";

export const GITHUB = "https://github.com/arthrod/open-legal-artifacts";

export interface Link {
  label: string;
  url: string;
}

export interface OriginalEntry {
  name: string;
  title: string;
  tagline: string;
  repoDir: string;
  links: Link[];
}

export type OpenCategory = "anthropic-built" | "partner-built" | "original-idea";

export interface OpenEntry {
  name: string;
  title: string;
  tagline: string;
  category: string;
  practiceArea: string;
  readerQuestion: string;
  anthropicCounterpart: string | null;
  status: string;
  hasDemo: boolean;
  hasSpec: boolean;
  hasReadme: boolean;
  inAppDemo: string | null;
}

export interface ExternalEntry {
  name: string;
  title: string;
  blurb: string;
  links: Link[];
}

export interface PracticeArea {
  id: string;
  label: string;
  filterLabel: string;
  caption: string;
}

export interface ReaderQuestion {
  id: string;
  label: string;
  caption: string;
}

export interface Taxonomies {
  practiceAreas: PracticeArea[];
  readerQuestions: ReaderQuestion[];
}

export interface Catalog {
  generatedAt: string;
  counts: { originals: number; open: number; external: number; originalIdeas: number };
  originals: OriginalEntry[];
  open: OpenEntry[];
  external: ExternalEntry[];
  taxonomies: Taxonomies;
}

export const catalog = raw as Catalog;

// Typed taxonomy defs — the single source of labels for the index toolbar
// and the at-rest reader-question grouping.
export const PRACTICE_AREAS: PracticeArea[] = catalog.taxonomies.practiceAreas;
export const READER_QUESTIONS: ReaderQuestion[] = catalog.taxonomies.readerQuestions;
